     9→
    10→namespace Nethermind.Crypto
    11→{
    12→    public static class EthereumEcdsaExtensions
    13→    {
    14→        private static readonly TxDecoder _txDecoder = TxDecoder.Instance;
    15→        public static AuthorizationTuple Sign(this IEthereumEcdsa ecdsa, PrivateKey signer, ulong chainId, Address codeAddress, ulong nonce)
    16→        {
    17→            KeccakRlpStream stream = new();
    18→            stream.WriteByte(Eip7702Constants.Magic);
    19→            AuthorizationTupleDecoder.EncodeWithoutSignature(stream, chainId, codeAddress, nonce);
    20→            Signature sig = ecdsa.Sign(signer, stream.GetValueHash());
    21→            return new AuthorizationTuple(chainId, codeAddress, nonce, sig);
    22→        }
    23→
    24→        public static void Sign(this IEthereumEcdsa ecdsa, PrivateKey privateKey, Transaction tx, bool isEip155Enabled = true)
    25→        {
    26→            if (tx.Type != TxType.Legacy)
    27→            {
    28→                tx.ChainId = ecdsa.ChainId;
    29→            }
    30→
    31→            ValueHash256 hash = ValueKeccak.Compute(Rlp.Encode(tx, true, isEip155Enabled, ecdsa.ChainId).Bytes);
    32→            tx.Signature = ecdsa.Sign(privateKey, in hash);
    33→
    34→            if (tx.Type == TxType.Legacy && isEip155Enabled)
    35→            {
    36→                tx.Signature.V = tx.Signature.V + 8 + 2 * ecdsa.ChainId;
    37→            }
    38→        }
    39→
    40→        /// <summary>
    41→        ///
    42→        /// </summary>
    43→        /// <param name="sender"></param>
    44→        /// <param name="tx"></param>
    45→        /// <returns></returns>
    46→        public static bool Verify(this IEthereumEcdsa ecdsa, Address sender, Transaction tx)
    47→        {
    48→            Address? recovered = ecdsa.RecoverAddress(tx);
    49→            return recovered?.Equals(sender) ?? false;
    50→        }
    51→
    52→        /// <summary>
    53→        ///
    54→        /// </summary>
    55→        /// <param name="tx"></param>
    56→        /// <param name="useSignatureChainId"></param>
    57→        /// <returns></returns>
    58→        public static Address? RecoverAddress(this IEthereumEcdsa ecdsa, Transaction tx, bool useSignatureChainId = false)
    59→        {
    60→            if (tx.Signature is null)
    61→            {
    62→                throw new InvalidDataException("Cannot recover sender address from a transaction without a signature.");
